SELECT Country FROM singer WHERE Age > 40
INTERSECT
SELECT Country FROM singer WHERE Age < 30;

SELECT a.Airline
FROM airlines a
WHERE EXISTS (
    SELECT 1 FROM flights f WHERE f.Airline = a.uid AND f.SourceAirport = 'APG'
)
AND EXISTS (
    SELECT 1 FROM flights f WHERE f.Airline = a.uid AND f.SourceAirport = 'CVO'
);

SELECT Name, Location, District
FROM shop
ORDER BY Number_products DESC;

SELECT e.Name
FROM employee e
WHERE e.Employee_ID NOT IN (SELECT Employee_ID FROM evaluation);

SELECT Document_ID FROM Paragraphs WHERE Paragraph_Text LIKE '%Brazil%'
INTERSECT
SELECT Document_ID FROM Paragraphs WHERE Paragraph_Text LIKE '%Ireland%';

SELECT p.first_name, p.country_code
FROM players p
WHERE EXISTS (
    SELECT 1 FROM matches m1 WHERE m1.winner_id = p.player_id AND m1.tourney_name = 'WTA Championships'
)
AND EXISTS (
    SELECT 1 FROM matches m2 WHERE m2.winner_id = p.player_id AND m2.tourney_name = 'Australian Open'
);

SELECT COUNT(*) FROM battle b
LEFT JOIN ship s ON b.id = s.lost_in_battle AND s.tonnage = '225'
WHERE s.id IS NULL;

SELECT Record_Company FROM orchestra WHERE Year_of_Founded < 2003
INTERSECT
SELECT Record_Company FROM orchestra WHERE Year_of_Founded > 2003;

SELECT Record_Company FROM orchestra WHERE Year_of_Founded < 2003
INTERSECT
SELECT Record_Company FROM orchestra WHERE Year_of_Founded > 2003;

SELECT DISTINCT f.student_id
FROM Friend f
INNER JOIN Likes l ON f.student_id = l.liked_id;

SELECT MIN(grade)
FROM Highschooler
WHERE ID NOT IN (SELECT student_id FROM Friend UNION SELECT friend_id FROM Friend);

SELECT state FROM Owners
INTERSECT
SELECT state FROM Professionals;

SELECT role_code, street, city, state
FROM Professionals
WHERE city LIKE '%West%';

SELECT first_name, last_name, email_address
FROM Owners
WHERE state LIKE '%North%';

SELECT name, age, weight
FROM Dogs
WHERE abandoned_yn = '1';
